import time
EPOCH = 1704067200000  # custom epoch, not unix epoch
WORKER_BITS = 10
SEQ_BITS = 12
MAX_SEQ = (1 << SEQ_BITS) - 1

class SnowflakeNode:
    def __init__(self, worker_id: int):
        assert 0 <= worker_id < (1 << WORKER_BITS)
        self.worker_id = worker_id
        self.last_ms = -1
        self.seq = 0

    def _now_ms(self) -> int:
        return int(time.time() * 1000) - EPOCH

    def next_id(self) -> int:
        now = self._now_ms()
        if now < self.last_ms:
            # Clock went backwards: refuse rather than duplicate.
            # Trade-off: availability loss beats silent collision.
            raise ClockRegression(self.last_ms - now)
        if now == self.last_ms:
            self.seq = (self.seq + 1) & MAX_SEQ
            if self.seq == 0:
                # Sequence exhausted in this ms: spin to next tick.
                while now <= self.last_ms:
                    now = self._now_ms()
        else:
            self.seq = 0
        self.last_ms = now
        return (now << (WORKER_BITS + SEQ_BITS)) | (self.worker_id << SEQ_BITS) | self.seq

class ClockRegression(Exception):
    pass
